{
    "parameters": {
        "properties": {
            "request": {
                "anyOf": [
                    {
                        "additionalProperties": {},
                        "type": "object"
                    },
                    {
                        "type": "string"
                    }
                ],
                ...
            }
        }
    }
}
```

